// NeuG form of the Neo4j BI query; contains no materialized-property reads.
// Render parameters with NeuG/scripts/benchmark/render_bi_node_indexes.py.
MATCH (tag:TAG)-[:HASTYPE]->(:TAGCLASS {name:'Single'}) OPTIONAL MATCH (m:POST:COMMENT)-[:HASTAG]->(tag) WHERE m.creationDate >= TIMESTAMP('2010-06-09 00:00:00') AND m.creationDate < TIMESTAMP('2010-09-17 00:00:00') WITH tag,count(m) AS w1 OPTIONAL MATCH (n:POST:COMMENT)-[:HASTAG]->(tag) WHERE n.creationDate >= TIMESTAMP('2010-09-17 00:00:00') AND n.creationDate < TIMESTAMP('2010-12-26 00:00:00') WITH tag,w1,count(n) AS w2 RETURN tag.name,w1,w2,CASE WHEN w1 >= w2 THEN w1-w2 ELSE w2-w1 END AS diff ORDER BY diff DESC,tag.name LIMIT 100;

